// Wraps tsc's single-file output in an IIFE so the Shims add nothing to the
// page's global scope except the APIs they install.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";

const compiled = readFileSync("build/shims.js", "utf8");
mkdirSync("dist", { recursive: true });
writeFileSync(
  "dist/tizen-sim-shims.js",
  "// Generated by `npm run build` in shims/. Do not edit by hand.\n" +
    "(function () {\n" +
    compiled +
    "})();\n",
);
